<form class="identity-content" method="POST" action="{{ $contact?route('crm.contact.update',$contact->id):route('crm.contact') }}">@csrf @if($contact)@method('PUT')@endif<label>Name<input class="field" name="name" value="{{ $contact->name??'' }}" required maxlength="200"></label><label>Company<select class="field" name="company_id"><option value="">Independent</option>@foreach($companyChoices as $item)<option value="{{ $item->id }}" @selected(($contact->company_id??null)==$item->id)>{{ $item->name }}</option>@endforeach</select></label><label>Email<input class="field" type="email" name="email" value="{{ $contact->email??'' }}"></label><label>Phone<input class="field" name="phone" value="{{ $contact->phone??'' }}"></label><label>Position<input class="field" name="position" value="{{ $contact->position??'' }}"></label><label>Segment<input class="field" name="segment" value="{{ $contact->segment??'' }}"></label><label>Lifecycle<select class="field" name="lifecycle">@foreach(['prospect','customer','inactive'] as $s)<option @selected(($contact->lifecycle??'prospect')===$s)>{{ $s }}</option>@endforeach</select></label><button class="btn">Save contact</button></form>
